import {marks,directions,pages} from './cartographer-content.mjs';
import {mapView,startMap,setMapPage,selectMapMark,placeMapMark,chooseMapEndpoint,selectMapRoute,appendMapMove,removeMapMove,clearMapRoute,addMapSupport,resumeMap,mapRoutes,checkMapRoutes,mapCheckMatches} from './cartographer-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const name=id=>marks.find(m=>m.id===id)?.name||id;
const direction=id=>directions.find(d=>d.id===id)?.label||id;
const pair=p=>p?`(${p.x}, ${p.y})`:'unplaced';
const quantity=(n,unit)=>`${n} ${unit}${n===1?'':'s'}`;
const screen=p=>`${50+p.x*100},${550-p.y*100}`;
const help='On this practice map, start at the origin, zero across and zero up. Read the across coordinate first, then the up coordinate. North is up, east is right, south is down and west is left. Each interval between neighboring points is one model metre. Going out and back counts both intervals, even when the lines overlap.';
function key(places){return `<ul class="cart-key">${marks.map(m=>`<li><span aria-hidden="true">${esc(m.symbol)}</span><strong>${esc(m.name)}</strong><span>${pair(places?.[m.id])}</span></li>`).join('')}</ul>`;}
function grid(places,results=null,interactive=false,selected='post'){
 const point=(x,y)=>({x,y});
 const svg=`<svg class="cart-grid-art" viewBox="0 0 600 600" role="img" aria-label="Fictional grid, coordinates zero to five. Across first, then up. Route A is solid; route B is dashed. Exact positions and paths are also given in text.">${Array.from({length:6},(_,n)=>`<path d="M50 ${50+n*100}H550M${50+n*100} 50V550" fill="none" stroke="#b1c2b3" stroke-width="2"/>`).join('')}<path d="M50 50V550H550" fill="none" stroke="#183f39" stroke-width="4"/>${['a','b'].map(side=>{const points=results?.[side]?.points;if(!points?.length)return '';const end=points.at(-1),x=50+end.x*100,y=550-end.y*100;return `<polyline class="cart-path-${side}" points="${points.map(screen).join(' ')}" fill="none" stroke="${side==='a'?'#235d42':'#9a5f14'}" stroke-width="${side==='a'?7:5}"${side==='b'?' stroke-dasharray="15 9"':''} stroke-linejoin="round"/>${side==='a'?`<circle cx="${x}" cy="${y}" r="17" fill="#e7f2df" stroke="#235d42" stroke-width="4"/>`:`<rect x="${x-13}" y="${y-13}" width="26" height="26" fill="none" stroke="#9a5f14" stroke-width="4"/>`}`;}).join('')}${Array.from({length:6},(_,row)=>Array.from({length:6},(_,x)=>{const y=5-row,p=point(x,y),mark=marks.find(m=>places?.[m.id]?.x===x&&places[m.id].y===y);return `<circle cx="${50+x*100}" cy="${550-y*100}" r="${mark?(interactive?20:12):4}" fill="${mark?'#fffdf5':'#183f39'}" stroke="#183f39" stroke-width="2"/>${!interactive?`<text x="${50+x*100}" y="${575-y*100}" text-anchor="middle" font-size="18" fill="#183f39">${pair(p)}</text>${mark?`<text x="${50+x*100}" y="${556-y*100}" text-anchor="middle" font-size="22" fill="#183f39">${esc(mark.symbol)}</text>`:''}`:''}`;}).join('')).join('')}</svg>`;
 return `<figure class="cart-grid-figure"><p class="cart-axis-top">↑ North / up · y</p><div class="cart-grid${interactive?' cart-grid-interactive':''}">${svg}${interactive?`<div class="cart-point-buttons" role="group" aria-label="Place ${esc(name(selected))} at a grid intersection">${Array.from({length:6},(_,row)=>Array.from({length:6},(_,x)=>{const y=5-row,mark=marks.find(m=>places?.[m.id]?.x===x&&places[m.id].y===y),isSelected=mark?.id===selected;return `<button type="button" data-map-point="${x},${y}" aria-label="Place ${esc(name(selected))} at ${pair(point(x,y))}${mark?`; ${esc(mark.name)} is here`:''}" aria-pressed="${isSelected}"><span class="cart-point-symbol" aria-hidden="true">${mark?esc(mark.symbol):''}</span><span>${pair(point(x,y))}</span></button>`;}).join('')).join('')}</div>`:''}</div><figcaption><strong>x · across / East →</strong><span>Origin (0, 0) is at the lower left. Five intervals join six points from 0 to 5.</span>${results?'<span>Route A: solid line, circle endpoint. Route B: dashed line, square endpoint. Overlapping journeys still count every travelled interval.</span>':''}</figcaption></figure>`;
}
function endpointText(r){return `<p class="cart-trip"><strong>Start:</strong> ${esc(name(r.from))} ${pair(r.places[r.from])}<br><strong>Destination:</strong> ${esc(name(r.to))} ${pair(r.places[r.to])}</p>`;}
function resultText(result,side,recorded=false){return `<section class="cart-route-result"><h3>Route ${side}</h3><p><strong>${quantity(result.steps,'interval')} travelled · ${quantity(result.distance,'model metre')}</strong></p><p>Endpoint: ${pair(result.points.at(-1))}. ${recorded?`Recorded arrival: ${result.arrived?'yes':'no'}. Recorded blocked command: ${result.blocked??'none'}.`:result.blocked!==null?`Stopped before command ${result.blocked}: it would leave the map. That command and all later commands were not travelled. The route is not complete.`:result.commands.length===0?'No commands yet; still at the start.':result.arrived?'Completed and arrived at the destination.':'Completed, ending away from the destination.'}</p></section>`;}
function commandText(commands){return commands.length?commands.map((id,i)=>`${i+1}. ${direction(id)}`).join('; '):'No commands';}
function pointsText(points){return points.map(pair).join(' → ');}
function segmentHelp(results){return `<div class="cart-segments">${['a','b'].map(side=>`<section><h3>Route ${side.toUpperCase()} intervals in order</h3>${results[side].points.length>1?`<ol>${results[side].points.slice(1).map((p,i)=>`<li>${pair(results[side].points[i])} to ${pair(p)}: one model metre</li>`).join('')}</ol>`:'<p>No intervals travelled.</p>'}</section>`).join('')}</div>`;}
function mapPage(r,v){return `<h2 id="cart-prompt" tabindex="-1">Where shall ${esc(name(v.mark))} go?</h2><p>Choose a landmark, then tap a labelled intersection to place or move it.</p><div class="cart-mark-choices" role="group" aria-label="Choose a landmark">${marks.map(m=>button(`data-map-mark="${m.id}" aria-pressed="${v.mark===m.id}"`,`${m.symbol} ${m.name}`,v.mark===m.id)).join('')}</div>${grid(r?.places,null,true,v.mark)}${key(r?.places)}<p>Read <strong>across first, then up</strong>. Try Café at (4, 2), then Bridge at (2, 4). What changed?</p><p class="tiny">Orchard numbers name covered plots. These pairs name meeting points of grid lines. This is an invented practice map.</p>${button('data-map-page="route"','Make a route',true)}`;}
function endpointChoices(r){return `<div class="cart-endpoints">${[['from','Start'],['to','Destination']].map(([which,label])=>`<label>${label}<select data-map-endpoint="${which}" id="cart-${which}">${marks.map(m=>`<option value="${m.id}"${r[which]===m.id?' selected':''}${r[which==='from'?'to':'from']===m.id?' disabled':''}>${esc(m.name)} · ${pair(r.places[m.id])}</option>`).join('')}</select></label>`).join('')}</div>`;}
function routePage(r,v){const results=mapRoutes(r),side=v.side.toLowerCase(),commands=r[side];return `<h2 id="cart-prompt" tabindex="-1">Build route ${v.side}, one interval at a time</h2>${endpointText(r)}<details id="cart-endpoint-options" data-round="${r.id}"><summary>Change start or destination</summary>${endpointChoices(r)}<p class="tiny">Changing the start, destination or map keeps both command lists. They run again from the current start.</p></details>${!results?'<p class="cart-notice">Place both the start and destination before travelling. <button type="button" class="text-button" data-map-page="map">Place the landmarks</button>.</p>':''}<div class="cart-side-choices" role="group" aria-label="Choose a route to edit">${['A','B'].map(s=>button(`data-map-side="${s}" aria-pressed="${v.side===s}"`,`Route ${s}${s===v.side?' · editing':''}`,s===v.side)).join('')}</div><div class="cart-moves" role="group" aria-label="Add one interval to route ${v.side}">${directions.map(d=>button(`data-map-move="${d.id}"`,d.label)).join('')}</div><p class="tiny">One move travels one model metre. Up to 12 commands per route; no diagonal moves.</p><div class="cart-route-diagram">${grid(r.places,results)}</div><section class="cart-command-list"><h3>Route ${v.side} commands (${commands.length} of 12)</h3>${commands.length?`<ol>${commands.map((id,i)=>`<li>${button(`data-map-remove="${i}" aria-label="Remove command ${i+1}: ${esc(direction(id))}"`,`${i+1}. ${direction(id)} · remove`)}${results?.[side].blocked!==null&&results?.[side].blocked<=i+1?'<span class="tiny">Not travelled</span>':''}</li>`).join('')}</ol>`:'<p>No commands yet. Choose a direction to begin.</p>'}${button('data-map-clear'+(commands.length?'':' disabled'),'Clear this route')}</section>${results?resultText(results[side],v.side):''}<aside class="cart-other-route"><h3>Route ${v.side==='A'?'B':'A'} is waiting</h3><p>${esc(commandText(r[side==='a'?'b':'a']))}</p>${results?resultText(results[side==='a'?'b':'a'],v.side==='A'?'B':'A'):''}</aside>${r.support.includes('segments')&&results?segmentHelp(results):''}${button('data-map-page="compare"','Compare both routes',true)}`;}
function checkView(c,index,current){return `<section class="cart-check" tabindex="-1"><h3>${current?'Latest check of this map':'Earlier recorded check'}${index===null?'':` ${index+1}`}</h3><p class="tiny">This check keeps its own map and commands. Later edits do not change these recorded results.</p>${endpointText(c)}${grid(c.places,{a:c.a,b:c.b})}${key(c.places)}${['a','b'].map(side=>`<div class="cart-recorded-route">${resultText(c[side],side.toUpperCase(),true)}<p><strong>Recorded commands:</strong> ${esc(commandText(c[side].commands))}</p><p><strong>Recorded travelled points:</strong> ${pointsText(c[side].points)}</p></div>`).join('')}<p><strong>Recorded length comparison:</strong> ${c.relation==='equal'?'A and B have equal travelled lengths.':`A is ${c.relation} than B.`}</p><p>${c.bothArrived?c.different?'Thank you, map-maker! Both arrived. A visitor can choose between your two different routes.':'Thank you, map-maker! Both arrived. These matching routes are valid; you could try a second way.':c.a.blocked!==null||c.b.blocked!==null?'You can revise either route. A shorter travelled prefix is not a completed shortcut when commands are blocked.':'You can revise either route. Look at each recorded endpoint: which route ended away from the destination?'}</p></section>`;}
function comparePage(r){const results=mapRoutes(r),latest=r.checks.at(-1);return `<h2 id="cart-prompt" tabindex="-1">Where did each route go?</h2>${endpointText(r)}${grid(r.places,results)}${results?`<div class="cart-live-results"><div>${resultText(results.a,'A')}<p>Commands: ${esc(commandText(r.a))}</p></div><div>${resultText(results.b,'B')}<p>Commands: ${esc(commandText(r.b))}</p></div></div>`:'<p class="cart-notice">Place the start and destination to compare routes. <button type="button" class="text-button" data-map-page="map">Return to the map</button>.</p>'}<p class="tiny">Each adjacent interval is one model metre. Count travel, including out-and-back intervals, rather than dots or covered plots.</p>${button(`data-map-check${results?'':' disabled'}`,'Check these routes',true)} ${button('data-map-page="route"','Change a route')}<p class="tiny">Up to 8 checks stay in this map. A ninth check removes the oldest.</p>${results&&r.support.includes('segments')?segmentHelp(results):''}${latest?checkView(latest,null,mapCheckMatches(r)):'<p>No check yet. Your map and both routes stay open for changes.</p>'}${r.checks.length>1?`<details><summary>Earlier recorded checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkView(c,i,false)).join('')}</details>`:''}`;}
function history(v){return `${v.rounds.length?`<details><summary>Our maps (${v.rounds.length} of 12)</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-map-resume="${r.id}" aria-current="${r.id===v.current?.id?'true':'false'}"`,`Map ${r.id}${r.id===v.current?.id?' (open)':''}: ${name(r.from)} to ${name(r.to)}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work is kept unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function cartographerPage(state){const v=mapView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#workshop">← Workshop</a> <a class="back" href="#post">Back to Post Office</a><h1>Cartographer’s Table</h1><p>The storm scattered our old signs. Make a map to help market visitors find their way.</p></header>`;if(v.status==='unavailable')return `<div class="cart-page">${heading}<section class="cart-sheet"><h2>Earlier work is safe</h2><p>This saved map uses a format we cannot continue here. It stays unchanged. The Workshop and Post Office remain open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.cartographer,null,2))}</pre></details></section></div>`;
 return `<div class="cart-page">${heading}<section class="cart-sheet"><nav class="cart-tabs" aria-label="Cartographer’s Table pages">${pages.map(p=>button(`data-map-page="${p}" aria-current="${v.page===p?'page':'false'}"`,p[0].toUpperCase()+p.slice(1),v.page===p)).join('')}</nav><p class="cart-status" id="cart-status" role="status" tabindex="-1"></p>${v.page==='map'?mapPage(r,v):r?v.page==='route'?routePage(r,v):comparePage(r):`<h2 id="cart-prompt" tabindex="-1">Start a practice map</h2><p>Place two landmarks, then make and compare your own routes.</p>${button('data-map-page="map"','Place landmarks',true)}`}<details id="cart-help"${r?.support.includes('help')?' open':''}><summary>Help us read the map</summary><p>${help}</p>${hearButton(help,'Hear the map explanation')}${button('data-map-support="together"',r?.support.includes('together')?'Thinking together recorded':'We thought together')}</details>${r?button('data-map-support="segments"',r.support.includes('segments')?'Numbered intervals are shown':'Show numbered intervals'):''}<section class="cart-new"><h2>A fresh sheet</h2><p class="tiny">Up to 12 readable maps stay here.${v.rounds.length>=12?` All spaces are used. Starting a blank map removes ${quantity(v.rounds.length-11,'oldest readable map')}.`:' Starting a blank map leaves earlier maps waiting within that limit.'}</p>${button('data-map-start','Start a new blank map')}</section></section>${history(v)}</div>`;
}
export function cartographerNotes(state){const v=mapView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Cartographer’s Table · earlier format</summary><pre>${esc(JSON.stringify(state.cartographer,null,2))}</pre></details>`;return `<details class="panel cart-page"><summary>Cartographer’s Table (${v.rounds.length} maps)</summary><p>Supported fictional coordinate and route practice. Equal model units and all labels are supplied. No independent map construction, physical measurement, decoding or shortest-path attainment is inferred. The latest 12 readable maps and 8 checks per map remain available; the notes download includes full original work.</p>${v.rounds.map(r=>`<section><h3>Map ${r.id}</h3>${key(r.places)}${endpointText(r)}<p>Live route A: ${esc(commandText(r.a))}. Live route B: ${esc(commandText(r.b))}.</p><p>Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${r.checks.map((c,i)=>checkView(c,i,i===r.checks.length-1&&mapCheckMatches(r))).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindCartographer(state,{save,render,focus}){
 const show=(message='',target='#cart-prompt')=>{const roundId=mapView(state).current?.id,options=document.querySelector('#cart-endpoint-options'),keepOptions=options?.open&&Number(options.dataset.round)===roundId;save();render();const nextOptions=document.querySelector('#cart-endpoint-options');if(nextOptions&&keepOptions)nextOptions.open=true;const status=document.querySelector('#cart-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('[data-map-page]',b=>{const changed=setMapPage(state,b.dataset.mapPage);show(changed?'':'No readable map is open and a new sheet could not be created. Original saved work is kept.',changed?'#cart-prompt':'#cart-status');});
 bind('[data-map-mark]',b=>{const changed=selectMapMark(state,b.dataset.mapMark);show(changed?`Place ${name(b.dataset.mapMark)} at a labelled intersection.`:'No readable map is open and a new sheet could not be created. Original saved work is kept.',`[data-map-mark="${b.dataset.mapMark}"]`);});
 bind('[data-map-point]',b=>{const [x,y]=b.dataset.mapPoint.split(',').map(Number),result=placeMapMark(state,x,y),mark=mapView(state).mark;show(result==='invalid'?'No readable map is open and a new map could not be created. Original saved work is kept; other destinations remain open.':result==='occupied'?'Another landmark is already at that point. Both landmarks have stayed where they were.':result==='same'?`${name(mark)} is already at (${x}, ${y}).`:`${name(mark)} is at (${x}, ${y}): ${x} across, then ${y} up.`,`[data-map-point="${x},${y}"]`);});
 document.querySelectorAll('[data-map-endpoint]').forEach(select=>select.addEventListener('change',()=>{const ok=chooseMapEndpoint(state,select.dataset.mapEndpoint,select.value);show(ok?'The route commands are kept and now run from the current start toward the current destination.':'Choose different landmarks for the start and destination.',`#${select.id}`);}));
 bind('[data-map-side]',b=>{selectMapRoute(state,b.dataset.mapSide);setMapPage(state,'route');show(`Editing route ${b.dataset.mapSide}.`,`[data-map-side="${b.dataset.mapSide}"]`);});
 const moveMessage={changed:'Move added. Earlier checks stay unchanged.',limit:'This route already has 12 commands. Remove a command before adding another.',boundary:'That move would leave the grid. No command was added.',blocked:'This route has a blocked command. Remove or clear commands before adding another.',missing:'Place both the start and destination first.',invalid:'Choose one of the four directions.'};
 bind('[data-map-move]',b=>{const result=appendMapMove(state,b.dataset.mapMove);show(moveMessage[result]||'The route is unchanged.',`[data-map-move="${b.dataset.mapMove}"]`);});
 bind('[data-map-remove]',b=>{const index=Number(b.dataset.mapRemove);removeMapMove(state,index);const v=mapView(state),length=v.current?.[v.side.toLowerCase()].length||0;show('Command removed. Earlier checks stay unchanged.',length?`[data-map-remove="${Math.min(index,length-1)}"]`:'[data-map-move]');});
 bind('[data-map-clear]',()=>{clearMapRoute(state);show('This route is empty. Earlier checks stay unchanged.','[data-map-move]');});
 bind('[data-map-check]',()=>{const check=checkMapRoutes(state);show(check?'This map and both routes have been checked. The recorded result is below.':'Place the start and destination before checking.',check?'.cart-check':'#cart-status');});
 bind('[data-map-support]',b=>{const changed=addMapSupport(state,b.dataset.mapSupport);show(!changed?'Help stays available. No support record was added because no readable map is open.':b.dataset.mapSupport==='segments'?'Numbered travelled intervals are shown below the routes.':'Thinking together recorded.',`[data-map-support="${b.dataset.mapSupport}"]`);});
 bind('[data-map-start]',()=>{const r=startMap(state);show(r?'A blank map is ready. Earlier checks stay in their own maps.':'A new map cannot be created because the saved map numbers have reached the supported limit. Existing maps remain available.',r?'#cart-prompt':'#cart-status');});
 bind('[data-map-resume]',b=>{resumeMap(state,Number(b.dataset.mapResume));show('Earlier map opened. Its recorded checks stay unchanged.');});
 document.querySelector('#cart-help')?.addEventListener('toggle',e=>{if(e.currentTarget.open){addMapSupport(state,'help');save();}});
 document.querySelectorAll('.cart-page [data-speak]').forEach(b=>b.addEventListener('click',()=>{addMapSupport(state,'audio');save();}));
}
